select jsonb_build_object('checked_at',clock_timestamp(),'expected',count(*),'exact',count(*)filter(where exact),'mismatches',coalesce(jsonb_agg(ref)filter(where not coalesce(exact,false)),'[]')) as verification from(select 'catalog_work_descriptions:1' as ref,(select to_jsonb(t) from public.catalog_work_descriptions t where t.work_id=987162003 and t.language='nl')='{"text":"Na de lange kustwandeling die zij in Het zoutpad beschreef, probeert Raynor Winn opnieuw een leven onder een dak op te bouwen. In haar relaas blijven zij en haar man Moth zich verbonden voelen met het landschap waarin zij onderweg leefden. Een aanbod brengt hen naar een boerderij in Cornwall, waar zij de grond weer ruimte voor natuur willen geven. Winn verbindt dat nieuwe begin met herinneringen, verlies en haar verhouding tot Moth. Het boek presenteert haar eigen ervaring van thuiskomen en buiten zijn.","work_id":987162003,"evidence":[{"note":"Exact existingDutchISBN9789463821049 andindependentlyreviewedWinnmemoir; narrative attributed, notverifiedlifefacts ormedicalclaim. Reuse existingWork5185/Edition5344.","type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p426420047"],"reference":"work:5185","checked_at":"2026-11-03T12:39:49.425Z","canonical_name_resolution":null},{"type":"original_substantive_source_review","review":"content-amendment-029.json","sources":["https://www.penguinrandomhouse.com/books/647652/the-wild-silence-by-raynor-winn/","https://data.bibliotheken.nl/id/nbt/p426420047"]},{"note":"Exact earliertransportfailure/unpublishedarchive retained, noretryorclaimofabsence. Actualhosteddecodedcoverorplaceholderseparatelyrequired.","type":"no_verified_cover_asset_retained","isbn13":"9789463821049","status":"no_verified_asset_retained","attempts":[{"status":"prior_source_failure_no_new_request","coverId":13010849,"receipt":"cover-archive-v2-readback.json","receiptSha256":"01f189d7785da46ad38b728eded6972350e6dbc066a98d304fcd35be46e12f27","historical